/** Códigos RESULT de L081 (cabecera del fuente y VALUE ARRAY VA_RESULT). */
public enum ResultadoL081 {
    OK(0), FUNCION_INCORRECTA(1), TIPO_MDA_INVALIDO(2), MDA_INVALIDO(3),
    OCURRENCIA_INVALIDA(4), TIPO_REGISTRO_INVALIDO(5), CSI_INVALIDO(6), ORIGEN_INVALIDO(7),
    AGRUPADOR_INVALIDO(8), IND_CUENTA_ORDENANTE_INVALIDO(9), HI_INVALIDO(10),
    SISTEMA_INVALIDO(11), PASO_INVALIDO(12), BASE_NO_DISPONIBLE(13),
    CONTROL_NO_EXISTE(14), CONTRATO_NO_EXISTE(15), ERROR_BASE(16),
    S016_DESACTIVADO(17), S016_INCORRECTO(18), LIBRERIA_NO_INICIADA(19),
    FECHA_PROCESO_INVALIDA(20), FECHA_CTA_ORDENANTE_INVALIDA(21),
    HORA_CTA_ORDENANTE_INVALIDA(22), FECHA_HORA_BD_MAS_RECIENTE(23);

    private final int codigo;
    ResultadoL081(int codigo) { this.codigo = codigo; }
    public int codigo() { return codigo; }
}

/** Errores de negocio se devuelven como resultado; los técnicos como excepción. */
public final class L081Exception extends RuntimeException {
    private final ResultadoL081 resultado;
    public L081Exception(ResultadoL081 r) { super(r.name()); this.resultado = r; }
    public ResultadoL081 resultado() { return resultado; }
}

// $SET SHARING = SHAREDBYRUNUNIT: una instancia por run unit con variables globales
// compartidas (I_RESULT, IA_GRUP_NUM, R_DMERR...). En Java el servicio es un singleton
// SIN estado mutable: todo dato de trabajo vive en variables locales o en un record
// por invocación, de modo que dos llamadas concurrentes no se pisan.

@Service
@RequiredArgsConstructor
public class AtributosCuentaService {

    private final AtomicBoolean iniciada = new AtomicBoolean(false);   // B_INICIO
    private final DataSourceHealth bd07;                               // B_BD07OPEN / ABRE_BD

    /** VALIDA_INICIO: sin S500L081INICIO previo, cualquier entry point responde 19. */
    private Optional<ResultadoL081> validaInicio() {
        if (!iniciada.get()) return Optional.of(ResultadoL081.LIBRERIA_NO_INICIADA);
        if (!bd07.disponible() && !bd07.reconecta()) {
            return Optional.of(ResultadoL081.BASE_NO_DISPONIBLE);          // 13
        }
        return Optional.empty();
    }
}
// En el modelo Spring, el pool de conexiones (HikariCP) reabre conexiones caídas por sí mismo;
// la verificación explícita se mantiene solo para devolver 13 con el mismo contrato.

@Component
@RequiredArgsConstructor
class ResolutorMedioAcceso {
    private final S016MedioAccesoClient s016;           // S016L458.S016_L458_BUSCA_MDA
    private final AtomicBoolean llamadaHabilitada = new AtomicBoolean(true);   // B_LLAMA_S016 (HI 4195)

    /** LLAMA_S016: medio de acceso de 16 dígitos a contrato y CSI. */
    ResultadoResolucion resuelve(String medioAcceso16) {
        if (!llamadaHabilitada.get()) return ResultadoResolucion.error(ResultadoL081.S016_DESACTIVADO);
        try {
            RespuestaS016 r = s016.buscaMda(medioAcceso16);
            if (r.dmsError() > 0) {
                log.warn("ERROR CALL S016: {}", r.dmsError());
                return ResultadoResolucion.error(ResultadoL081.S016_INCORRECTO);   // 18
            }
            return ResultadoResolucion.ok(r.contrato(), r.csi());
        } catch (ServicioNoDisponibleException e) {
            return ResultadoResolucion.error(ResultadoL081.S016_DESACTIVADO);      // 17: no se pudo ligar
        }
    }
}
